import{_ as l,a0 as d,w as p,s as n,I as t,x as s,a1 as e,A as o,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"如何在 Fedora 上安裝 VSCodium | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Fedora 上安裝 VSCodium | LCTT (202311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Fedora 上安裝 VSCodium | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Fedora 上安裝 VSCodium | LCTT (202311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202311/20231031 Install VSCodium on Fedora","title":"如何在 Fedora 上安裝 VSCodium","tag":"202311","desc":""},"relativePath":"202311/20231031 Install VSCodium on Fedora.md","filePath":"[post].md"}'),u={name:"202311/20231031 Install VSCodium on Fedora.md"};function m(g,i,k,h,f,b){const a=d("Link");return p(),n("div",null,[i[34]||(i[34]=t("h1",{id:"如何在-fedora-上安裝-vscodium",tabindex:"-1"},[s("如何在 Fedora 上安裝 VSCodium "),t("a",{class:"header-anchor",href:"#如何在-fedora-上安裝-vscodium","aria-label":"Permalink to “如何在 Fedora 上安裝 VSCodium”"},"​")],-1)),i[35]||(i[35]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202311/26/134531enn7h0bn7z97977b.png",alt:""})],-1)),i[36]||(i[36]=t("blockquote",null,[t("p",null,"VSCodium 是微軟 VS Code 真正開源的版本，它可以輕鬆安裝在 Fedora 上。具體方法如下。")],-1)),i[37]||(i[37]=t("p",null,"Visual Studio Code（VS Code）是微軟開發的一款流行的跨平台文本編輯器。它基於 Electron 框架構建，被開發人員廣泛用於編碼和文本編輯任務。VS Code 的核心，稱為 “Code - OSS”，是開源的，並在 MIT 許可證下分發。然而，微軟添加了特定的自定義功能，並在專有許可下發布了其品牌版本的編輯器。",-1)),t("p",null,[i[2]||(i[2]=s("為了解決有關 ",-1)),e(a,{href:"https://code.visualstudio.com/docs/getstarted/telemetry"},{default:o(()=>[...i[0]||(i[0]=[s("遙測",-1)])]),_:1}),i[3]||(i[3]=s(" 和許可的問題，有一個名為 “",-1)),e(a,{href:"https://itsfoss.com/vscodium/"},{default:o(()=>[...i[1]||(i[1]=[s("VSCodium",-1)])]),_:1}),i[4]||(i[4]=s("” 的替代方案，它是社區驅動、禁用遙測且獲得 MIT 許可的 VS Code 版本。",-1))]),i[38]||(i[38]=t("p",null,[t("img",{src:"https://itsfoss.com/content/images/2023/10/codium-on-fedora.png",alt:"VSCodium running on Fedora 39"})],-1)),i[39]||(i[39]=t("p",null,"在本教程中，我將指導你完成在 Fedora Linux 系統上安裝和運行 VSCodium 的過程。",-1)),i[40]||(i[40]=t("p",null,"有三種方法可以做到這一點：",-1)),t("ol",null,[i[12]||(i[12]=t("li",null,"從發佈頁面下載 rpm 文件進行安裝。但是，你需要重複該過程才能更新軟件包（這可能會令人沮喪）。",-1)),t("li",null,[i[8]||(i[8]=s("添加 ",-1)),e(a,{href:"https://gitlab.com/paulcarroty/vscodium-deb-rpm-repo"},{default:o(()=>[...i[5]||(i[5]=[s("paulcarroty",-1)])]),_:1}),i[9]||(i[9]=s(" 倉庫（如 ",-1)),e(a,{href:"https://vscodium.com/"},{default:o(()=>[...i[6]||(i[6]=[s("VSCodium",-1)])]),_:1}),i[10]||(i[10]=s(" 網站所述）。因此，當你 ",-1)),e(a,{href:"https://itsfoss.com/update-fedora/"},{default:o(()=>[...i[7]||(i[7]=[s("更新你的 Fedora 系統",-1)])]),_:1}),i[11]||(i[11]=s(" VScodium 也會得到更新（這是相當無縫的）。",-1))]),i[13]||(i[13]=t("li",null,"使用 flatpak 版本，你可能已經嘗試過從 GNOME “軟件”中安裝該版本（我有過同樣的糟糕經歷，因此可能會有所不同）。",-1))]),t("p",null,[i[16]||(i[16]=s("第一個非常簡單，即從 ",-1)),e(a,{href:"https://github.com/VSCodium/vscodium/releases"},{default:o(()=>[...i[14]||(i[14]=[s("發佈頁面",-1)])]),_:1}),i[17]||(i[17]=s(" 下載並 ",-1)),e(a,{href:"https://itsfoss.com/install-rpm-files-fedora/"},{default:o(()=>[...i[15]||(i[15]=[s("安裝 RPM 文件",-1)])]),_:1}),i[18]||(i[18]=s("。那麼，讓我們切入主題並遵循其他兩種方法。",-1))]),i[41]||(i[41]=r('<h3 id="方法-1-通過添加倉庫來安裝-vscodium" tabindex="-1">方法 1：通過添加倉庫來安裝 VSCodium <a class="header-anchor" href="#方法-1-通過添加倉庫來安裝-vscodium" aria-label="Permalink to “方法 1：通過添加倉庫來安裝 VSCodium”">​</a></h3><p>打開終端：你可以通過在應用菜單中搜索 “Terminal” 來打開終端。</p><p>添加 GPG 密鑰：以便包管理器信任倉庫的打包者。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo rpmkeys --import https://gitlab.com/paulcarroty/vscodium-deb-rpm-repo/-/raw/master/pub.gpg</span></span></code></pre></div><p>添加 VSCodium 倉庫：以下命令會將倉庫添加到你的 Fedora 系統。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>printf &quot;[gitlab.com_paulcarroty_vscodium_repo]\\nname=download.vscodium.com\\nbaseurl=https://download.vscodium.com/rpms/\\nenabled=1\\ngpgcheck=1\\nrepo_gpgcheck=1\\ngpgkey=https://gitlab .com/paulcarroty/vscodium-deb-rpm-repo/-/raw/master/pub.gpg\\nmetadata_expire=1h&quot; | sudo tee -a /etc/yum.repos.d/vscodium.repo</span></span></code></pre></div><p>安裝VSCodium：現在你已經添加了 VSCodium 存儲庫，你可以使用以下命令安裝它（喜歡前沿軟件的人可以將軟件包名稱替換為 <strong>codium-insiders</strong> 來安裝 insider 版本）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install codium</span></span></code></pre></div><p>啓動 VSCodium：你現在可以從應用菜單或在終端中運行以下命令來啓動 VSCodium：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>codium</span></span></code></pre></div><h4 id="刪除-vscodium" tabindex="-1">刪除 VSCodium <a class="header-anchor" href="#刪除-vscodium" aria-label="Permalink to “刪除 VSCodium”">​</a></h4><p>如果你不喜歡 VSCodium 以及它基於 Electron 的事實，或者改用 Neovim。你可以使用以下命令刪除它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf remove codium</span></span></code></pre></div><p>你可以將倉庫和簽名添加到你的系統中，也可以不保留（為什麼不）。</p><p>因此，讓我們擺脱該倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo rm /etc/yum.repos.d/vscodium.repo</span></span></code></pre></div><h3 id="方法-2-使用-flatpak-安裝-vscodium" tabindex="-1">方法 2：使用 Flatpak 安裝 VSCodium <a class="header-anchor" href="#方法-2-使用-flatpak-安裝-vscodium" aria-label="Permalink to “方法 2：使用 Flatpak 安裝 VSCodium”">​</a></h3><p>你也可以安裝 Flatpak。因此，以下是在 Fedora 上使用 Flatpak 安裝 VSCodium 的步驟：</p><p>你可以通過啓用 Flathub 直接在 Fedora 上安裝它，如果你使用的是最新版本之一併且為 Fedora 啓用了第三方倉庫，那麼可能會啓用該功能。只需在 GNOME “軟件” 應用中搜索 VSCodium 並單擊安裝即可。</p><p><img src="https://itsfoss.com/content/images/2023/10/codium-flatpak-fedora.png" alt="Installing the flatpak from Gnome Software"></p><p>不過，由於某些原因運行舊版本的用户，或者他們可能有一個未啓用 Flatpak 的分叉，也可以效仿。</p><p>安裝 Flatpak 並啓用 Flathub：Fedora 通常預裝了 Flatpak。如果尚未安裝，你可以使用以下命令進行安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install flatpak</span></span></code></pre></div><p>要啓用 Flathub 倉庫，請使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak remote-add --if-not-exists flathub https://flathub.org/repo/flathub.flatpakrepo</span></span></code></pre></div><p>現在你已經設置了 Flatpak，你可以使用 Flathub 倉庫安裝 VSCodium。運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak install flathub com.vscodium.codium</span></span></code></pre></div><p>啓動 VSCodium：你可以使用以下命令通過 Flatpak 啓動 VSCodium：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak run com.vscodium.codium</span></span></code></pre></div><p>或者，你也可以在應用菜單中搜索 “VSCodium” 並從那裏啓動它。</p><p>就是這樣！ 你現在應該已經使用 Flatpak 在 Fedora 系統上安裝並運行了 VSCodium。</p><p>要刪除它，請使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo flatpak uninstall com.vscodium.codium</span></span></code></pre></div><h3 id="附言" tabindex="-1">附言 <a class="header-anchor" href="#附言" aria-label="Permalink to “附言”">​</a></h3><p>如果你使用過 VS Code，那麼你不會發現這兩個軟件之間有任何區別。這只是為了開放和免受微軟版本的邪惡遙測的影響。</p><p>在 Fedora，我首先安裝了 Flatpak 版本，但在 Wayland 會話中，VSCodium 沒有顯示任何窗口裝飾（這顯然是默認的）。這讓我很難用鼠標導航。</p><p><img src="https://itsfoss.com/content/images/2023/10/codium-flatpak-no-decorations.png" alt="VSCodium flatpak showing no window decorations."></p><p>我嘗試了一些方法來解決這個問題，但由於 Fflatpak 配置文件的位置很奇怪，所以沒有成功。如果有人有或能找到解決上述問題的辦法，請在下面發表評論。不過，使用 rpm 版本倒是天衣無縫（也許懷疑論者對替代軟件包管理系統的看法是對的）。</p><p>擴展和插件在大部分情況下都沒有問題。你也可以按照本教程在企業 Linux 系列的任何發行版（如 Alma Linux、Rocky Linux 等）上安裝。</p><p><em>（題圖：MJ/5f39d386-d28c-4b3d-97a8-b498290d54f7）</em></p><hr>',41)),t("p",null,[i[20]||(i[20]=s("via: ",-1)),e(a,{href:"https://itsfoss.com/install-vscodium-fedora/"},{default:o(()=>[...i[19]||(i[19]=[s("https://itsfoss.com/install-vscodium-fedora/",-1)])]),_:1})]),t("p",null,[i[25]||(i[25]=s("作者：",-1)),e(a,{href:"https://itsfoss.com/author/anuj/"},{default:o(()=>[...i[21]||(i[21]=[s("Anuj Sharma",-1)])]),_:1}),i[26]||(i[26]=s(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:o(()=>[...i[22]||(i[22]=[s("lujun9972",-1)])]),_:1}),i[27]||(i[27]=s(" 譯者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:o(()=>[...i[23]||(i[23]=[s("geekpi",-1)])]),_:1}),i[28]||(i[28]=s(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:o(()=>[...i[24]||(i[24]=[s("wxy",-1)])]),_:1})]),t("p",null,[i[31]||(i[31]=s("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...i[29]||(i[29]=[s("LCTT",-1)])]),_:1}),i[32]||(i[32]=s(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:o(()=>[...i[30]||(i[30]=[s("Linux中國",-1)])]),_:1}),i[33]||(i[33]=s(" 榮譽推出",-1))])])}const V=l(u,[["render",m]]);export{v as __pageData,V as default};
